mapper.sql:
 		from code as a
 		left join codeGroup b on b.cg_id = a.codeGroup_cg_id
		where 1=1
 		 AND a.cd_use = #{shUseNy}
         AND a.cd_delny = #{shDelNy}


					AND a.cd_register BETWEEN #{shDateStart} AND #{shDateEnd}
					AND a.cd_modifDate BETWEEN #{shDateStart} AND #{shDateEnd}



            AND b.cg_id = #{shValue}
            AND b.cg_name LIKE CONCAT('%',#{shValue},'%')
            AND a.cd_name LIKE CONCAT('%',#{shValue},'%')
